/*2. Import retail investor csv files from "Jupyter Hub" (TAQ code).*/
%macro drive(dir,ext); 
   %local cnt filrf rc did memcnt name; 
   %let cnt=0;          

   %let filrf=mydir;    
   %let rc=%sysfunc(filename(filrf,&dir)); 
   %let did=%sysfunc(dopen(&filrf));
   %if &did ne 0 %then %do;   
