* Join in Say-on-pay votes to UnexpPR; 
proc sql; 
create table UnexpComp_CEO as select distinct 
d1.*, d2.CompanyID as ISS_CompID, d2.MeetingID, d2.MeetingDate, d2.ItemDesc, d2.VoteResult, d2.ISSRec, d2.SOPPct1, d2.SOPPCt2, d2.SOPPct3 
from UnexpPR_TEMP2 as d1 
left join ISSMeetings as d2 
	on d1.gvkey=d2.gvkey and d1.datadate=d2.datadate; 
quit; 

proc sort data=UnexpComp_CEO; by gvkey fyear descending tenureyrs; 
proc sort data=UnexpComp_CEO nodupkey; by gvkey fyear; 
run; 

* First year of required CEO pay ratio reporting: Output to Stata for decomposition of pay ratio into expected/unexpected portions; 
proc sort data=UnexpComp_CEO (where=(mdy(12,31,2017)<=FYEDATE<=mdy(12,30,2018) and Pay_Ratio ne .)) out=UnexpPR nodupkey; by gvkey; 
run; 

****** Now use this file to run the "Proxy Dates_FF reference portfolios" SAS program and to estimate unexpected pay ratios; 
PROC EXPORT DATA= UnexpPR 
            OUTFILE= "[redacted-path-014ddc8affae]" 
            DBMS=STATA REPLACE; 
RUN; 

**** All years for unexplained CEO pay (numerator); 
PROC EXPORT DATA= UnexpComp_CEO 
            OUTFILE= "[redacted-path-404a625b1963]" 
            DBMS=STATA REPLACE; 
RUN;

* Format Equilar data for link to Compustat/Execucomp data; 
data EquilarID_Data_TEMP; set CPR.EquilarID_Data (where=(FY_End ne .)); 
datadate=intnx('month',datepart(FY_End),0,'end'); format datadate date9.;

* Bring in risk-free rates (interpolate missing yearly rates); 
data riskfree; set CPR.RiskFree; 
twoyr=(oneyr+threeyr)/2;  
fouryr=(threeyr+fiveyr)/2; 
sixyr=(fiveyr+sevenyr)/2; 
eightyr=(sixyr+tenyr)/2; 
nineyr=(eightyr+tenyr)/2; 
run; 

data riskfree; set riskfree; 
 * rates are in percentages, need to be in fractions; 
  array X  
   oneyr twoyr threeyr fouryr fiveyr sixyr sevenyr eightyr nineyr tenyr; 
  do over X; 
   X=X/100; 
  end; 
 keep DATE oneyr twoyr threeyr fouryr fiveyr sixyr sevenyr eightyr nineyr tenyr;

* Right to work states; 
data RighttoWork; set CPR.RighttoWork; 
proc sort data=RighttoWork nodupkey; by State_Code; 
run; 

* Join in QCEW industry-region compensation for nearest MSA; 
proc sql; 
create table COMP4 as select distinct 
d1.*, dC.GEO_ID as CensusGeo_ID, dC.CensusDist, dC.CollegeGradPct_2017, dC.CollegeGradPct_2018, 
dQ.AREACODE as QCEW_AREACODE, dQ.QCEW_Dist, dCPI.CPI_Annual, 
repnull(dQ2017.Annual_Average_Pay,dQ2017B.Annual_Average_Pay) as IndRegionComp_2017, 
repnull(dQ2018.Annual_Average_Pay,dQ2018B.Annual_Average_Pay) as IndRegionComp_2018, 
case when d1.FYEAR=2017 then repnull(dQ2017.Annual_Average_Pay,dQ2017B.Annual_Average_Pay) 
	when d1.FYEAR=2018 then repnull(dQ2018.Annual_Average_Pay,dQ2018B.Annual_Average_Pay) else . end as IndRegionComp, 
case when d1.FYEAR=2017 then dC.CollegeGradPct_2017 when d1.FYEAR=2018 then dC.CollegeGradPct_2018 else . end as CollegeGradPct, 
case when dRW.State_Code ne '' then 1 else 0 end as RightToWork, 
dHC.Pay_Ratio, case when dHC.GVKEY ne . then 1 else 0 end as HCData_Available, dHC.EGC, dHC.lag_EGC, 
case when dHC.EMPLOYEE_MEDIAN_PAY ne . then dHC.EMPLOYEE_MEDIAN_PAY else dAC.TOTAL_SEC*1000/dHC.Pay_Ratio end as EMPLOYEE_MEDIAN_PAY, 
dAC.CO_PER_ROL, dAC.TOTAL_SEC, dAC.AGE, dAC.TenureYrs, dAC.EXEC_FULLNAME,

* Create LINK FILE with RavenPack via the individual yearly files on ISIN and firm NAME (Press Release edition); 
proc sql; 
create table mylib.RPDLink as select distinct 
d1.*, d2.* 
from RPNA.RP_COMPANY_MAPPING (where=(DATA_TYPE='CUSIP' and DATA_VALUE ne '')) as d1 
inner join CPR_Sample (where=(NCUSIP ne '')) as d2 
	on substr(d1.DATA_VALUE,1,6)=substr(d2.NCUSIP,1,6) and (d1.RANGE_START<=d2.datadate and (d1.RANGE_END=. or d2.datadate<d1.RANGE_END)); 
quit; 

proc sort data=mylib.RPDLink; by GVKEY descending YEAR; 
proc sort data=mylib.RPDLink nodupkey; by GVKEY; 
proc download data=mylib.RPDLink; 
run; 

proc download data=RPNA.WRDS_RP_SOURCE_LIST; 
run; 

* Now join to RavenPack to pull all press releases using the link file; 
%macro RPD(RP_YEAR); 

proc sql; 
* Press release edition; 
create table RP&RP_YEAR as select distinct 
d1.GVKEY, d2.* 
from mylib.RPDLink as d1 
inner join RPNA.PR_EQUITIES_&RP_YEAR (drop=PRODUCT_KEY EVALUATION_METHOD COUNTRY_CODE COMPANY) as d2 
	on d1.RP_ENTITY_ID=d2.RP_ENTITY_ID;

*variables to extract from IBES; 
%let ibes_vars= ticker value fpedats anndats anntims revdats measure fpi estimator analys pdf usfirm; 
%let ibes_where1=where=(measure='EPS' and usfirm=1 and fpi in ('6','7') and &bdate<=fpedats<=&edate); * Captures forecasts of annual earnings in the 90 days prior to announcement; 
%let ibes_where2=where=(missing(repdats)=0 and missing(anndats)=0 and 0<intck('day',anndats,repdats)<=90); * Note: intck is the interval function that counts the numnber of 'day' between anndats and repdats; 

*define a set of auxiliary macros; 
%include 'cibeslink.sas'; 
%include 'IBES_Sample.sas'; 
%include 'iclink.sas'; 

*CIBESLINK macro will create a linking table CIBESLNK between IBES ticker and Compustat GVKEY 
*based on IBES ticker-CRSP permno (ICLINK) and CCM CRSP permno - Compustat GVKEY (CSTLINK2) link; 
%CIBESLINK (begdt=&bdate, enddt=&edate); 
%IBES_SAMPLE (infile=cibeslnk, ibes1_where=&ibes_where1, ibes2_where=&ibes_where2, ibes_var=&ibes_vars);

* Upload list of dates with GVKEY-FYEAR; 
proc upload data=CPR.UnexpComp_CEO (keep=GVKEY LPERMNO LPERMCO datadate FYEAR Pay_Ratio Proxy_FDATE); 
data DATELIST; set UnexpComp_CEO; 
* Upload data from Kenneth French's website for daily returns and size/BM reference portfolio breakpoints; 
proc upload data=CPR.Size_bm_ref_portfolios_ewd; 
proc upload data=CPR.Mv_breakpoints; 
proc upload data=CPR.Bm_breakpoints;

* Conversion of Ken French reference portfolio data into useable format; 
proc sort data=Size_bm_ref_portfolios_ewd; by DATE; run; 

proc transpose data=Size_bm_ref_portfolios_ewd 
	out=Temp1 (rename = (_NAME_=PNAME COL1=RET)); 
   by DATE;
run; 

proc sql;
create table Size_BM_REFEW as select distinct
DATE, PNAME, RET, 
case when substr(upcase(compress(PNAME)),1,5)='SMALL' then 0 
	when substr(upcase(compress(PNAME)),1,3)='TWO' then 1 
	when substr(upcase(compress(PNAME)),1,5)='THREE' then 2 
	when substr(upcase(compress(PNAME)),1,4)='FOUR' then 3 
	when substr(upcase(compress(PNAME)),1,3)='BIG' then 4 else . end as MVQ, 
case when substr(upcase(reverse(compress(PNAME))),1,3)='WOL' then 0 
	when substr(upcase(reverse(compress(PNAME))),1,1)='2' then 1 
	when substr(upcase(reverse(compress(PNAME))),1,1)='3' then 2 
	when substr(upcase(reverse(compress(PNAME))),1,1)='4' then 3 
	when substr(upcase(reverse(compress(PNAME))),1,4)='HGIH' then 4 else . end as BMQ

/*4. Merge 'pay ratio sample' and 'retail investor data' using 'CRSP-TAQ link' (https://wrds-www.wharton.upenn.edu/pages/get-data/linking-suite-wrds/taq-crsp-link/).*/

/*4-a. Download a 'CRSP-TAQ link' table.*/
%let wrds=wrds-cloud.wharton.upenn.edu 4016;

data to_download(compress=yes);
set wrdsapps.taqmclink (where=(year(date)>2016));
run;

proc download data=to_download out=crsp_taq_link; run;
endrsubmit;

signoff;

data CPR.crsp_taq_link; set crsp_taq_link; run;

* Bring in fiscal year-end date based on RDATE of 10-K filing in SEC Analytics; 
data Exhibits_10K; set WRDSSEC.EXHIBITS (where=(substr(strip(FORM),1,4)='10-K' and SEQUENCE=1)); 
run; 

*COMPUSTAT EXTRACT; 
proc sql; 
* First link to nearest 10-K filing (within +/- 20 days); 
create table Temp10K as select distinct 
d1.GVKEY, d1.CIK, d1.datadate, d1.FYEAR, 
d2.FDATE, d2.RDATE, d2.WRDSFNAME, abs(intck('day',d1.datadate,d2.RDATE)) as DayDiff 
from comp.funda (keep=&comp_list &comp_where) as d1 
inner join Exhibits_10K as d2 
	on d1.CIK=d2.CIK and intnx('day',d1.datadate,-20,'same')<=d2.RDATE<= intnx('day',d1.datadate,20,'same'); 
quit; 

proc sort data=Temp10K; by GVKEY datadate DayDiff FDATE; 
proc sort data=Temp10K nodupkey; by GVKEY datadate; 
run; 

proc sql; 
create table comp (drop=consol indfmt datafmt popsrc) as select distinct 
d1.*, csho*prcc_f as mcap, repnull(d2.RDATE,d1.datadate) as FYEDATE, d2.WRDSFNAME, d2.FDATE as FDATE_10K, dC.ADDZIP 
from comp.funda (keep=&comp_list &comp_where) as d1

* a) Link Gvkey with Lpermno;
proc sql;
create table comp1 as select distinct 
a.*, b.LPERMCO, b.LPERMNO, b.LINKDT, b.LINKENDDT, d3.NCUSIP, dT.TICKER as CRSP_TIC, 
d4.NAMEDT_BEG as FirstCRSPDate, year(a.datadate)-year(d4.NAMEDT_BEG) as CRSPAGE, 
dEC.DIVYIELD as DIVYIELD_EC 
from comp (where=(&bdate<=datadate<=&edate)) as a
left join lnk as b
   	on a.gvkey=b.gvkey and (linkdt<=a.datadate<=linkenddt or (linkdt<=a.datadate and linkenddt=.E) or (b.linkdt=.B and a.datadate<=b.linkenddt)) and b.usedflag=1 
left join MSENAMES_SUM as d3
	on b.LPERMNO=d3.PERMNO and d3.NAMEDT_BEG <= a.datadate and a.datadate<=d3.NAMEENDT_END
left join MSENAMES_AGE as d4
	on b.LPERMNO=d4.PERMNO 
left join MSENAMES_TICKER as dT 
	on b.LPERMNO=dT.PERMNO and dT.NAMEDT_BEG <= a.datadate and a.datadate<=dT.NAMEENDT_END
left join comp.CODIRFIN as dEC 
	on a.GVKEY=dEC.GVKEY and a.FYEAR=dEC.YEAR;  
quit; 

proc sort data=comp1 nodupkey; by gvkey datadate; 
run; 

***** Bring in equity volatility (from CRSP); 
proc sql; 
create table CRSPMKT as select distinct 
CALDT, VWRETD, usdcnt, ewretd, TOTVAL 
from crspq.msix; 
quit; 

proc sort data=CRSPMKT; by CALDT; 
data CRSPMKT; set CRSPMKT; by CALDT; 
Row_Num= _N_; 
lag_CALDT= lag(CALDT); 
run; 

* Measures of daily market returns using CRSP DAILY files for NYSE + AMEX + NASDAQ; 
proc sql; 
create table CRSPMKT_D as select distinct 
CALDT, VWRETD, usdcnt, ewretd, TOTVAL
from crspq.dsix; 
run; 

proc sort data=CRSPMKT_D; by CALDT;

data temp10; set crsp.dsf (keep = permno date prc bid ask bidlo askhi ret retx vol CFACPR SHROUT); run; 
proc sort; by permno date; run; 
data temp20; set crsp.dsedelist (keep = permno dlstcd dlstdt dlamt dlret); run;
proc sort; by permno dlstdt; run;

proc sql;
create table tempD1 as select distinct
d1.*, dM.Row_NUM, dM.VWRETD, 
d2.dlstcd, d2.dlamt, d2.dlret as dlret_C, 
case when substring(put(d2.dlstcd, 3.) from 1 for 1) in('4','5','7') and d2.dlret in(.A,.S,.T,.P,.) then -.3
	else d2.dlret end as dlret 
from temp10 as d1
left join temp20 as d2

proc download data=comp.anncomp; 
proc download data=anncomp_CEO; 
proc download data=TENURE; 
run; 

* Create dataset that combines Execucomp + Equilar data (when Execucomp is NOT available) for oustanding equity awards; 
* NOTE: Execucomp data will have outstanding awards for both CEO and CFO, while Equilar will only track the CEO outstanding equity; 
data EQOnlyObs; set anncomp_CEO (where=(Execucomp_D=0 and Equilar_D=1)); 
run; 

proc sql; 
create table EC_outstandingawards as select distinct 
d1.GVKEY, d1.FYEAR as YEAR, d1.datadate, 1 as outstand, 
case when d2.CO_PER_ROL ne . then 1 else 0 end as Execucomp_D, 
0 as Equilar_D, '' as EqCompID, '' as EqExecID, put(d2.CO_PER_ROL,8.) as CO_PER_ROL, d2.outawdnum, 
d2.expric, d2.ExDate, d2.opts_unex_exer as OPT_UNEX_EXER_NUM, d2.opts_unex_unexer as OPT_UNEX_UNEXER_NUM, d2.opts_unex_unearn as opts_unearned_num, 
d2.eip_shrs_unvest_num, d2.eip_shrs_unvest_val, d2.shrs_unvest_num, d2.shrs_unvest_val
from COMP2 as d1 
inner join comp.outstandingawards as d2

create table MSENAMES_CUSIP as select distinct
permno, ncusip, min(NAMEDT) as NAMEDT_BEG, max(NAMEENDT) as NAMEENDT_END
from crsp.msenames 
group by permno, ncusip
order by permno, ncusip;
quit; 

proc sql; 
  create table compA (drop=consol indfmt datafmt popsrc) 
   as select *, csho*prcc_f as mcap, compress(put(sich,8.)) as SIC_Code 
   from comp.funda (keep=&comp_listA &comp_whereA); 
quit;

* ISS Say-on-pay voting data; 
data VA_2003_2019; set CPR.VA_2003_2019 (where=(ISSagendaItemID = 'M0550')); 
SOPPct1= VotedAgainst               / (VotedAgainst+VotedFor); 
SOPPct2= VotedAgainst               / (VotedAgainst+VotedFor+VotedAbstain); 
SOPPct3=(VotedAgainst+VotedAbstain) / (VotedAgainst+VotedFor+VotedAbstain); 
run; 

* Join in Say-on-Pay voting based on first meeting following the proxy filing; 
proc sql; 
create table ISSMeetings as select distinct 
d1.GVKEY, d1.LPERMCO, d1.Proxy_FDATE, d1.datadate, d1.Pay_Ratio, 
d2.* 
from UnexpPR_TEMP2 as d1 
inner join VA_2003_2019 as d2 
	on d1.LPERMCO=d2.PERMCO and d1.Proxy_FDATE<d2.MeetingDate<=intnx('month',d1.Proxy_FDATE,9,'same');

* Format Equilar data for link to Compustat/Execucomp data; 
data EquilarID_Data_TEMP; set CPR.EquilarID_Data (where=(FY_End ne .)); 
datadate=intnx('month',datepart(FY_End),0,'end'); format datadate date9.; 
YEAR= year(datadate); 
CompID= substr(Company_ID,1,index(Company_ID,'.')-1); 
ExecID= substr(Executive_ID,index(Executive_ID,'N.')+2,10); 
COPERROL= compress(CompID) || '.' || compress(ExecID); 
proc sort data=EquilarID_Data_TEMP nodupkey; by CompID ExecID Year;

* Note: Execucomp is in 000s, while Equilar has data in raw form. Divide Equilar to match; 
data Equilar_outstawards; set CPR.Equilar_outstawards (where=(FY_End ne .)); 
datadate=intnx('month',datepart(FY_End),0,'end'); format datadate date9.; 
YEAR= year(datadate); 
CompID= substr(Executive_ID,1,index(Executive_ID,'.')-1); 
ExecID= substr(Executive_ID,index(Executive_ID,'N.')+2,10); 
COPERROL= compress(CompID) || '.' || compress(ExecID); 
NumSecurities= input(compress(Number_of_Securities,"0123456789.","k"),8.)/1000; 
if Equity_Type='Exercisable Options' then OPT_UNEX_EXER_NUM=NumSecurities; else OPT_UNEX_EXER_NUM=.; 
if Equity_Type='Exercisable Options' then OPT_UNEX_EXER_VAL=Value/1000; else OPT_UNEX_EXER_VAL=.; 
if Equity_Type='Unexercisable Options' then OPT_UNEX_UNEXER_NUM=NumSecurities; else OPT_UNEX_UNEXER_NUM=.; 
if Equity_Type='Unexercisable Options' then OPT_UNEX_UNEXER_VAL=Value/1000; else OPT_UNEX_UNEXER_VAL=.; 
if Equity_Type='Unearned EIP Options' then opts_unearned_num=NumSecurities; else opts_unearned_num=.; 
if Equity_Type='Unvested Stock' then shrs_unvest_num=NumSecurities; else shrs_unvest_num=.; 
if Equity_Type='Unvested Stock' then shrs_unvest_val=Value/1000; else shrs_unvest_val=.; 
if Equity_Type='EIP Awards' then eip_shrs_unvest_num=NumSecurities; else eip_shrs_unvest_num=.; 
if Equity_Type='EIP Awards' then eip_shrs_unvest_val=Value/1000; else eip_shrs_unvest_val=.;

data Equilar_anncomp; set CPR.Equilar_anncomp (where=(FY_End ne .)); 
datadate=intnx('month',datepart(FY_End),0,'end'); format datadate date9.; 
YEAR= year(datadate); 
CompID= substr(Company_ID,1,index(Company_ID,'.')-1); 
ExecID= substr(Executive_ID,index(Executive_ID,'N.')+2,10); 
COPERROL= compress(CompID) || '.' || compress(ExecID); 
CEOAGE= AGE-FY; 
proc sort data=Equilar_anncomp nodupkey; by CompID ExecID Year;

* Option compensation awards; 
data Equilar_OptionAwards; set CPR.Equilar_OptionAwards (where=(FY_End ne .)); 
datadate=intnx('month',datepart(FY_End),0,'end'); format datadate date9.; 
YEAR= year(datadate); 
CompID= substr(Executive_ID,1,index(Executive_ID,'.')-1); 
ExecID= substr(Executive_ID,index(Executive_ID,'N.')+2,10); 
