* Stock compensation awards; 
data Equilar_StockAwards; set CPR.Equilar_StockAwards (where=(FY_End ne .)); 
datadate=intnx('month',datepart(FY_End),0,'end'); format datadate date9.; 
YEAR= year(datadate); 
CompID= substr(Executive_ID,1,index(Executive_ID,'.')-1); 
ExecID= substr(Executive_ID,index(Executive_ID,'N.')+2,10); 
COPERROL= compress(CompID) || '.' || compress(ExecID);

* IP awards; 
data Equilar_IPAwards; set CPR.Equilar_IPAwards (where=(FY_End ne .)); 
datadate=intnx('month',datepart(FY_End),0,'end'); format datadate date9.; 
YEAR= year(datadate); 
CompID= substr(Executive_ID,1,index(Executive_ID,'.')-1); 
ExecID= substr(Executive_ID,index(Executive_ID,'N.')+2,10); 
COPERROL= compress(CompID) || '.' || compress(ExecID); 
if Award_Classification='Annual Award' then AnnualAwardDum=1; else AnnualAwardDum=0; 
if strip(Metric_s_)='' then NumPerfMetrics= 0; 
	else NumPerfMetrics= countc(Metric_s_,';')+1;
